//! Idroid Security & Trusted Device Pairing Subsystem
//!
//! Enforces Apple/Google-grade strict device authorization:
//! - Persists authorized paired devices in `~/.config/idroid/trusted_devices.json`.
//! - Automatically authorizes USB loopback connections (physical cable access).
//! - Verifies optical QR pairing tokens generated by this Mac.
//! - Blocks unrecognized/unpaired devices on the local Wi-Fi from accessing
//!   clipboard, notifications, camera, or system controls.
//! - Emits live authorization prompts to macOS when a new device attempts connection,
//!   allowing the user to [Authorize] or [Block & Reject].

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use std::sync::mpsc::Sender;
use std::sync::{LazyLock, Mutex};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct TrustedDevice {
    pub device_id: String,
    pub device_name: String,
    pub brand: String,
    pub paired_at: u64,
    pub last_seen: u64,
    pub last_ip: String,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct PendingAuthInfo {
    pub request_id: String,
    pub device_id: String,
    pub device_name: String,
    pub brand: String,
    pub ip: String,
    pub requested_at: u64,
}

pub struct PendingAuthEntry {
    pub info: PendingAuthInfo,
    pub responder: Sender<bool>,
}

pub static ACTIVE_PAIRING_TOKEN: LazyLock<Mutex<Option<String>>> = LazyLock::new(|| Mutex::new(None));
pub static TRUSTED_DEVICES_CACHE: LazyLock<Mutex<Vec<TrustedDevice>>> = LazyLock::new(|| Mutex::new(load_trusted_devices_from_disk()));
pub static PENDING_AUTH_REQUESTS: LazyLock<Mutex<HashMap<String, PendingAuthEntry>>> = LazyLock::new(|| Mutex::new(HashMap::new()));

fn get_storage_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/tmp".into());
    let mut path = PathBuf::from(home);
    path.push(".config");
    path.push("idroid");
    let _ = fs::create_dir_all(&path);
    path.push("trusted_devices.json");
    path
}

fn load_trusted_devices_from_disk() -> Vec<TrustedDevice> {
    let file_path = get_storage_path();
    if let Ok(content) = fs::read_to_string(&file_path) {
        if let Ok(devices) = serde_json::from_str::<Vec<TrustedDevice>>(&content) {
            return devices;
        }
    }
    Vec::new()
}

fn save_trusted_devices_to_disk(devices: &[TrustedDevice]) {
    let file_path = get_storage_path();
    if let Ok(json) = serde_json::to_string_pretty(devices) {
        let _ = fs::write(file_path, json);
    }
}

pub fn set_active_pairing_token(token: &str) {
    if let Ok(mut lock) = ACTIVE_PAIRING_TOKEN.lock() {
        *lock = Some(token.to_string());
    }
}

pub fn is_pairing_token_valid(token: &str) -> bool {
    if token.is_empty() {
        return false;
    }
    if let Ok(lock) = ACTIVE_PAIRING_TOKEN.lock() {
        if let Some(ref active) = *lock {
            return active == token;
        }
    }
    false
}

pub fn is_device_trusted(device_id: &str) -> bool {
    if device_id.is_empty() {
        return false;
    }
    if let Ok(lock) = TRUSTED_DEVICES_CACHE.lock() {
        return lock.iter().any(|d| d.device_id == device_id);
    }
    false
}

pub fn trust_device(device: TrustedDevice) {
    if device.device_id.is_empty() {
        return;
    }
    if let Ok(mut lock) = TRUSTED_DEVICES_CACHE.lock() {
        if let Some(existing) = lock.iter_mut().find(|d| d.device_id == device.device_id) {
            existing.device_name = device.device_name;
            existing.brand = device.brand;
            existing.last_seen = device.last_seen;
            existing.last_ip = device.last_ip;
        } else {
            lock.push(device);
        }
        save_trusted_devices_to_disk(&lock);
    }
}

pub fn update_trusted_device_seen(device_id: &str, ip: &str, now: u64) {
    if let Ok(mut lock) = TRUSTED_DEVICES_CACHE.lock() {
        if let Some(d) = lock.iter_mut().find(|d| d.device_id == device_id) {
            d.last_seen = now;
            if !ip.is_empty() {
                d.last_ip = ip.to_string();
            }
            save_trusted_devices_to_disk(&lock);
        }
    }
}

pub fn register_pending_auth(info: PendingAuthInfo, responder: Sender<bool>) {
    if let Ok(mut lock) = PENDING_AUTH_REQUESTS.lock() {
        lock.insert(info.request_id.clone(), PendingAuthEntry { info, responder });
    }
}

pub fn remove_pending_auth(request_id: &str) -> Option<PendingAuthEntry> {
    if let Ok(mut lock) = PENDING_AUTH_REQUESTS.lock() {
        lock.remove(request_id)
    } else {
        None
    }
}

// MARK: - Tauri Commands

#[tauri::command]
pub fn get_trusted_devices() -> Vec<TrustedDevice> {
    if let Ok(lock) = TRUSTED_DEVICES_CACHE.lock() {
        lock.clone()
    } else {
        Vec::new()
    }
}

#[tauri::command]
pub fn revoke_trusted_device(device_id: String) -> Result<bool, String> {
    if let Ok(mut lock) = TRUSTED_DEVICES_CACHE.lock() {
        let before_len = lock.len();
        lock.retain(|d| d.device_id != device_id);
        let removed = lock.len() < before_len;
        if removed {
            save_trusted_devices_to_disk(&lock);
            // If active companion session is this device, disconnect immediately
            if let Ok(mut sess_guard) = super::types::COMPANION_SESSION.lock() {
                *sess_guard = None;
            }
            if let Ok(mut writer_guard) = super::companion::COMPANION_WRITER.lock() {
                *writer_guard = None;
            }
            super::emit_to_windows("trusted_devices_updated", serde_json::to_value(&*lock).unwrap_or_default());
            return Ok(true);
        }
    }
    Ok(false)
}

#[tauri::command]
pub fn approve_device_authorization(request_id: String) -> Result<bool, String> {
    if let Some(entry) = remove_pending_auth(&request_id) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        trust_device(TrustedDevice {
            device_id: entry.info.device_id.clone(),
            device_name: entry.info.device_name,
            brand: entry.info.brand,
            paired_at: now,
            last_seen: now,
            last_ip: entry.info.ip,
        });

        let _ = entry.responder.send(true);
        super::emit_to_windows("device_authorization_resolved", serde_json::json!({
            "request_id": request_id,
            "approved": true
        }));
        if let Ok(lock) = TRUSTED_DEVICES_CACHE.lock() {
            super::emit_to_windows("trusted_devices_updated", serde_json::to_value(&*lock).unwrap_or_default());
        }
        return Ok(true);
    }
    Err("Pending authorization request not found or expired".into())
}

#[tauri::command]
pub fn reject_device_authorization(request_id: String) -> Result<bool, String> {
    if let Some(entry) = remove_pending_auth(&request_id) {
        let _ = entry.responder.send(false);
        super::emit_to_windows("device_authorization_resolved", serde_json::json!({
            "request_id": request_id,
            "approved": false
        }));
        return Ok(true);
    }
    Err("Pending authorization request not found or expired".into())
}

#[tauri::command]
pub fn get_security_status() -> serde_json::Value {
    let trusted_count = if let Ok(lock) = TRUSTED_DEVICES_CACHE.lock() {
        lock.len()
    } else {
        0
    };

    let pending: Vec<PendingAuthInfo> = if let Ok(lock) = PENDING_AUTH_REQUESTS.lock() {
        lock.values().map(|e| e.info.clone()).collect()
    } else {
        Vec::new()
    };

    serde_json::json!({
        "strict_mode": true,
        "trusted_devices_count": trusted_count,
        "pending_requests": pending,
        "active_pairing_ready": ACTIVE_PAIRING_TOKEN.lock().map(|t| t.is_some()).unwrap_or(false)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pairing_token_validation() {
        set_active_pairing_token("sec-token-12345");
        assert!(is_pairing_token_valid("sec-token-12345"));
        assert!(!is_pairing_token_valid("invalid-token"));
        assert!(!is_pairing_token_valid(""));
    }

    #[test]
    fn test_trusted_device_lifecycle() {
        let test_dev = TrustedDevice {
            device_id: "test-device-uuid-99".into(),
            device_name: "Test Galaxy S23".into(),
            brand: "Samsung".into(),
            paired_at: 1000,
            last_seen: 1000,
            last_ip: "192.168.1.50".into(),
        };

        trust_device(test_dev.clone());
        assert!(is_device_trusted("test-device-uuid-99"));
        assert!(!is_device_trusted("unknown-device-00"));

        let _ = revoke_trusted_device("test-device-uuid-99".into());
        assert!(!is_device_trusted("test-device-uuid-99"));
    }

    #[test]
    fn test_pending_auth_resolution() {
        let (tx, rx) = std::sync::mpsc::channel();
        let info = PendingAuthInfo {
            request_id: "req-test-1".into(),
            device_id: "dev-test-1".into(),
            device_name: "Mom's Phone".into(),
            brand: "Samsung".into(),
            ip: "192.168.1.99".into(),
            requested_at: 2000,
        };

        register_pending_auth(info, tx);
        let res = approve_device_authorization("req-test-1".into());
        assert!(res.is_ok());
        assert_eq!(rx.recv().unwrap(), true);
        assert!(is_device_trusted("dev-test-1"));

        // Cleanup
        let _ = revoke_trusted_device("dev-test-1".into());
    }
}

